{
  "core_question": "Assessing the clinical, legal, and financial implications of converting a nonprofit rural community hospital to for-profit via sale‑leaseback and charitable foundation spin‑out",
  "rationale": "The board must evaluate patient care continuity (healthcare), tax‑exempt status and transaction legality (legal), and valuation, financing, and cash‑flow impacts (finance).",
  "routes": ["healthcare", "legal", "finance"],
  "sub_questions": {
    "healthcare": "What clinical and operational factors—such as patient safety metrics, staffing levels, quality reporting obligations, and CMS/Medicaid compliance—should the hospital board evaluate when converting from nonprofit to for-profit status and executing a sale‑leaseback of its real estate?",
    "legal": "What are the key legal considerations—including IRS 501(c)(3) compliance, charitable foundation structuring, sale‑leaseback transaction mechanics, state hospital licensing requirements, and fiduciary duties—that affect the board’s decision to convert the nonprofit hospital to for-profit and spin out a charitable foundation?",
    "finance": "What financial analyses—covering asset valuation, lease‑back cost versus benefit, projected cash flows, tax implications, capital structure changes, and impact on the board’s fiduciary responsibilities—should the board conduct before approving this transaction?"
  },
  "requires_recency_disclosure": true,
  "recency_notes": "IRS 501(c)(3) rules post‑2024, sale‑leaseback tax treatment updates, recent CMS reimbursement policy changes, and state licensing regulations may be stale."
}
